/* Lessons content — stages 1-2. Schema: intro, question, analogy, analogyFail, explain[], code, codeNotes[], output, why, sim, mistakes[], practices[], quiz[], takeaways[], recall, todo, anim{title,steps[]} */
export const LESSONS_A={
'prog-what':{intro:'You already give instructions every day. Programming is writing them so clearly that even a very fast but very literal computer can follow them.',question:'If you had a robot helper that takes everything literally, how carefully would you word “make tea”?',analogy:'A recipe card. Ingredients = data, steps = instructions, cook = computer. If a step is vague (“add some salt”), results vary wildly.',analogyFail:'Where it breaks: a human cook guesses. A computer never guesses — vague steps crash or do the wrong thing. Precision is the whole game.',explain:['A <b>program</b> is a list of exact instructions plus the data they work on. Your music app, bank app, and games are all programs.','Programs do three things: take <b>input</b> (taps, files, sensors), <b>process</b> it (calculate, decide, repeat), and produce <b>output</b> (screen, sound, files).','You write programs in a <b>programming language</b> — a small, strict language with no small talk. Java is one of the most used.'],code:`// A program is input -> process -> output\n// Input:  two numbers. Process: add. Output: sum.\nint a = 4;\nint b = 5;\nint sum = a + b;        // process\nSystem.out.println(sum); // output: 9`,codeNotes:['Lines 3-4 store data in named boxes.','Line 5 processes: adds them.','Line 6 outputs the result.'],output:'9',why:'The computer did not “understand” adding like you do. It followed the + instruction on the two stored values and printed the result.',sim:{kind:'arith',label:'Change the numbers and operator — the computer just follows orders.',fields:[{v:'4'},{o:['+','-','*','/']},{v:'5'}]},mistakes:[{bad:'“The computer will figure out what I mean.”',why:'Computers take everything literally. “Sort of 5” is meaningless to them.',fix:'Say exactly what to do: add 5, print the result, stop.'},{bad:'Thinking data and instructions are the same.',why:'Data (4, 5) sits still. Instructions (+, print) act on it.',fix:'Label each line: is this storing, doing, or showing?'},{bad:'Starting with a huge app idea.',why:'Big programs are hundreds of small instruction lists combined.',fix:'Start with input → one step → output. Grow from there.'}],practices:[{title:'Label the parts',task:'Look at the code above. Write I (input/data), P (process), or O (output) next to each line.',hint:'Lines with = store data. + processes. println shows.',sol:'a, b, sum declarations = data/input; a + b = process; println = output.'},{title:'Write a 5-step recipe',task:'Write exact steps for “brush teeth” as if for a literal robot. No step may assume guessing.',hint:'Include amounts, order, and when to stop.',sol:'Example: 1 pick up brush, 2 add pea-size paste, 3 brush top teeth 30s, 4 brush bottom 30s, 5 rinse 5s, stop.'}],quiz:[{id:'q1',prompt:'What is a program?',options:[{t:'Exact instructions + data a computer follows',ok:true},{t:'A vague idea the computer guesses at'},{t:'Only the screen you see'},{t:'A physical computer part'}],explain:'A program = precise instructions operating on data.'},{id:'q2',prompt:'Input → process → output: which is “print sum”?',options:[{t:'Output',ok:true},{t:'Input'},{t:'Storage device'},{t:'Compiler'}],explain:'Printing shows a result, so it is output.'},{id:'q3',prompt:'Why must instructions be exact?',options:[{t:'Computers follow them literally and never guess',ok:true},{t:'Computers get bored otherwise'},{t:'Exact code runs on paper only'},{t:'It makes files smaller'}],explain:'Literal execution is why precision matters.'}],takeaways:['A program = exact instructions + data.','Input → process → output explains every app.','Computers never guess; precision is kindness to them.','Java is one language for writing such instructions.'],recall:'Say in one sentence: what does a program do with input?',todo:'Find one app you used today and name its input, process, and output.',anim:{title:'Recipe becomes program',steps:[{caption:'A recipe lists ingredients (data).',html:'<div class="pipe"><div class="box"><b>Ingredients</b><br>flour · eggs · 180°C</div><span class="arr">→</span><div class="box"><b>Steps</b><br>mix → bake → cool</div></div>'},{caption:'A program lists data the same way.',html:'<div class="viz"><div class="varbox"><div class="nm">a</div><div class="vl">4</div></div><div class="varbox"><div class="nm">b</div><div class="vl">5</div></div></div>'},{caption:'Then instructions act on it, and output appears.',html:'<div class="pipe"><div class="box"><b>Process</b><br>a + b = 9</div><span class="arr">→</span><div class="box"><b>Output</b><br>print 9</div></div>'}]}},
'algorithm':{intro:'An algorithm is just a recipe that is clear enough for a machine: finite steps, clear order, and a definite end.',question:'How would you teach a friend who has never been to your street to reach your door by phone?',analogy:'Morning routine: alarm → brush → dress → eat. Same order daily, ends when you leave. A loop-free algorithm feels like this.',analogyFail:'Where it breaks: “get dressed nicely” is an opinion, not a step. Algorithms need testable steps like “put on blue shirt”.',explain:['An <b>algorithm</b> has: input, clear steps in order, and an end. “Sort these 5 cards” with steps qualifies; “be creative” does not.','Good steps are <b>unambiguous</b> (one meaning), <b>ordered</b> (do step 2 after 1), and <b>finite</b> (they stop).','Programmers compare algorithms by correctness first, then speed: does it always give the right answer, and roughly how many steps?'],code:`// Algorithm: max of two numbers\n// Input: a, b. Output: the larger.\nint a = 7, b = 4;\nint max;\nif (a > b) {\n  max = a;\n} else {\n  max = b;\n}\nSystem.out.println(max); // 7`,codeNotes:['Steps run in order: store, compare, pick, print.','The if is a decision point — still exact.','It always ends after printing.'],output:'7',why:'Compare 7 > 4 is true, so max = 7. Any two numbers end at print — finite and exact.',sim:{kind:'cond',label:'Try values: the algorithm picks a branch and always finishes.',fields:[{v:'7'}]},mistakes:[{bad:'“Step 3: do the needful.”',why:'Vague verbs cannot execute.',fix:'Replace with measurable action: “add 1 spoon sugar, stir 10 times.”'},{bad:'Forgetting the stop condition.',why:'“Keep stirring” forever is not an algorithm.',fix:'Add an end: “stir 10 times, then stop.”'},{bad:'Steps in wrong order.',why:'“Bake, then mix” fails.',fix:'Number steps; check each needs only earlier results.'}],practices:[{title:'Spot the vague step',task:'Which is NOT a good algorithm step? A) “add 200g flour” B) “bake 20 min at 180°C” C) “make it tasty”.',hint:'Can a robot test it?',sol:'C — “tasty” cannot be tested. Rewrite: “add 1 tsp salt”.'},{title:'Write min-of-three',task:'Write 6 or fewer steps to find the smallest of x, y, z.',hint:'Compare two, keep winner, compare with third.',sol:'1 set m=x. 2 if y<m set m=y. 3 if z<m set m=z. 4 output m.'}],quiz:[{id:'q1',prompt:'What must an algorithm have?',options:[{t:'Clear ordered steps and an end',ok:true},{t:'At least 100 steps'},{t:'A computer to run on'},{t:'Fancy words'}],explain:'Finite, ordered, unambiguous steps.'},{id:'q2',prompt:'“Keep guessing until it feels right” fails because…',options:[{t:'It has no definite end',ok:true},{t:'It is too short'},{t:'Guessing is illegal'},{t:'It uses numbers'}],explain:'No testable stop = not an algorithm.'},{id:'q3',prompt:'Code above with a=2, b=9 prints?',options:[{t:'9',ok:true},{t:'2'},{t:'0'},{t:'It never ends'}],explain:'9 > 2, so else branch picks b.'}],takeaways:['Algorithm = exact steps + order + end.','Each step must be testable by a literal follower.','Order matters; check what each step needs.'],recall:'What three things make steps “algorithm-quality”?',todo:'Write sandwich-making steps (max 8) a robot could follow.',anim:{title:'Vague vs exact',steps:[{caption:'Vague step: robot freezes.',html:'<div class="pipe"><div class="box"><b>Step</b><br>“make it nice”</div><span class="arr">→</span><div class="box"><b>Robot</b><br>⁉️ which action?</div></div>'},{caption:'Exact steps: robot flows.',html:'<div class="pipe"><div class="box"><b>1</b> add 200g flour</div><span class="arr">→</span><div class="box"><b>2</b> bake 20 min</div><span class="arr">→</span><div class="box"><b>3</b> stop</div></div>'},{caption:'Same idea in code: compare, pick, print, stop.',html:'<div class="viz"><div class="varbox"><div class="nm">max</div><div class="vl">7</div></div></div>'}]}},
'source-code':{intro:'Source code is the human-readable text you write. The computer later translates it — but humans must read it first, including future you.',question:'Why do chefs write recipes instead of just filming themselves once?',analogy:'A recipe book vs the meal. The book (source) can be shared, edited, and re-cooked. The meal (running app) disappears after eating.',analogyFail:'Where it breaks: you can still eat without the recipe. A computer cannot run without translated code — source alone does nothing until built.',explain:['<b>Source code</b> = plain-text instructions in a language like Java. Files end in <b>.java</b>.','Code has strict <b>syntax</b> (spelling/grammar). One missing semicolon can stop translation.','We write for two readers: the translator (strict) and humans (need clear names and layout).'],code:`// Hello.java — source code (human readable)\npublic class Hello {\n  public static void main(String[] args) {\n    System.out.println("Hi, future programmer!");\n  }\n}`,codeNotes:['Line 1 is a comment — for humans only.','Lines 2-3 wrap the program in a class + starting point.','Line 4 is the real instruction.'],output:'Hi, future programmer!',why:'The translator keeps line 4 as an instruction and ignores the comment. Running prints the text.',sim:{kind:'concat',label:'Source text builds output text. Try joining words.',fields:[{v:'Hi, '},{v:'future programmer!'}]},mistakes:[{bad:'Editing the app instead of the code.',why:'The running app is output; fixes go in source.',fix:'Change .java, rebuild, run again.'},{bad:'Ignoring one red semicolon error.',why:'Syntax is all-or-nothing for the translator.',fix:'Read the first error line, fix, rebuild.'},{bad:'Names like a1, x2, tmp.',why:'Works for the machine, painful for humans.',fix:'Use total, userName, price.'}],practices:[{title:'Find the syntax',task:'Which line would break translation? A) // hi B) System.out.println("hi") C) System.out.println("hi");',hint:'Java statements end with ;',sol:'B — missing semicolon. C is correct.'},{title:'Rename well',task:'Rename int a1 (price of apples) to a good name.',hint:'What is it? Use full words.',sol:'int applePrice; or int priceApples;'}],quiz:[{id:'q1',prompt:'Source code is…',options:[{t:'Human-readable text the translator builds from',ok:true},{t:'The running app itself'},{t:'Electricity in wires'},{t:'A password'}],explain:'Source is the recipe text; the app is the meal.'},{id:'q2',prompt:'Java source files end with…',options:[{t:'.java',ok:true},{t:'.exe'},{t:'.jpg'},{t:'.txt only'}],explain:'By convention and tooling: .java.'},{id:'q3',prompt:'Why do comments exist?',options:[{t:'Explain why for humans; ignored by translator',ok:true},{t:'Make code run faster'},{t:'Required on every line'},{t:'Encrypt code'}],explain:'Comments help readers, never change behavior.'}],takeaways:['Source code is text humans write and edit.','Syntax must be exact; comments are free notes.','Name things for humans, not just the machine.'],recall:'What are the two readers of source code?',todo:'Open Hello.java (next lessons) and add a comment with your name.',anim:{title:'Source → translator → app',steps:[{caption:'You write source (.java).',html:'<div class="pipe"><div class="box"><b>Hello.java</b><br>println("Hi")</div></div>'},{caption:'Translator checks syntax strictly.',html:'<div class="pipe"><div class="box"><b>javac</b><br>missing ; ? STOP</div><span class="arr">→</span><div class="box"><b>Hello.class</b><br>bytecode</div></div>'},{caption:'Running shows the app.',html:'<div class="pipe"><div class="box"><b>Run</b><br>java Hello</div><span class="arr">→</span><div class="box"><b>Output</b><br>Hi!</div></div>'}]}},
'execute':{intro:'Your code does not run directly. It is fetched, decoded, and executed — billions of tiny steps per second — using memory as a workbench.',question:'If a chef can only hold one card at a time, how does the kitchen still produce a feast?',analogy:'Kitchen: recipe shelf (storage), counter (memory/RAM), chef hands (CPU). Ingredients move shelf → counter → hands, one step at a time.',analogyFail:'Where it breaks: chefs improvise and multitask. A CPU core does exactly one tiny operation per tick — speed comes from billions of ticks.',explain:['<b>CPU</b> executes one tiny operation per cycle: fetch instruction, decode it, execute it. Billions of cycles per second.','<b>RAM (memory)</b> holds running code and data — fast but erased at power-off. Disk/SSD keeps files long-term.','<b>Machine code</b> is 0s/1s the CPU truly understands. Java compiles to bytecode, then the JVM translates to machine steps.'],code:`// What the machine sees (simplified)\n// LOAD 4 into slot A\n// LOAD 5 into slot B\n// ADD A, B -> C\n// PRINT C            // shows 9`,codeNotes:['Fetch: get next instruction.','Decode: what does ADD mean?','Execute: do it, move to next.'],output:'9',why:'Four tiny steps, each trivial, combine into “add and print”. Speed × simplicity = power.',sim:{kind:'arith',label:'Each tiny step is exact. Change values, watch one ADD.',fields:[{v:'4'},{o:['+']},{v:'5'}]},mistakes:[{bad:'“RAM and disk are the same.”',why:'RAM is the counter (fast, temporary); disk is the shelf (slow, permanent).',fix:'Running data lives in RAM; files live on disk.'},{bad:'“CPU understands Java.”',why:'CPU understands machine code only.',fix:'Java → bytecode → machine steps via JVM.'},{bad:'“Faster code means fewer words.”',why:'Short code can do more work.',fix:'Count steps the machine does, not lines you see.'}],practices:[{title:'Order the cycle',task:'Order: A) execute B) fetch C) decode.',hint:'You must get it before reading it.',sol:'B fetch → C decode → A execute.'},{title:'RAM vs disk',task:'Where does a running variable live? Where does Hello.java live?',hint:'Counter vs shelf.',sol:'Variable in RAM; Hello.java file on disk.'}],quiz:[{id:'q1',prompt:'The CPU cycle order is…',options:[{t:'Fetch → decode → execute',ok:true},{t:'Execute → fetch → decode'},{t:'Decode → save → sleep'},{t:'Print → fetch → eat'}],explain:'Get it, understand it, do it.'},{id:'q2',prompt:'RAM is like…',options:[{t:'Kitchen counter: fast workspace, cleared after',ok:true},{t:'Recipe book on shelf forever'},{t:'The chef’s hat'},{t:'A printer'}],explain:'Fast, temporary working space.'},{id:'q3',prompt:'What does the CPU directly run?',options:[{t:'Machine code (0s and 1s)',ok:true},{t:'Java source text'},{t:'English recipes'},{t:'Comments'}],explain:'Everything must become machine steps.'}],takeaways:['CPU: fetch → decode → execute, billions/sec.','RAM = fast temporary counter; disk = long-term shelf.','Java runs via bytecode + JVM, not directly on CPU.'],recall:'Name the three CPU steps in order.',todo:'Explain fetch-decode-execute to someone in 30 seconds.',anim:{title:'Fetch-decode-execute',steps:[{caption:'1 FETCH: grab next card from counter.',html:'<div class="pipe"><div class="box"><b>Memory</b><br>ADD A,B</div><span class="arr">→</span><div class="box"><b>CPU</b><br>got it</div></div>'},{caption:'2 DECODE: what does ADD mean?',html:'<div class="pipe"><div class="box"><b>CPU</b><br>ADD = combine numbers</div></div>'},{caption:'3 EXECUTE: do it, store 9, next card.',html:'<div class="viz"><div class="varbox"><div class="nm">C</div><div class="vl">9</div></div></div>'}]}},
'java-intro':{intro:'Java runs banks, Android apps, Minecraft, and big websites. You learn it because it is strict in a helpful way and jobs love it.',question:'Why would a beginner pick a language that forces extra rules?',analogy:'Training wheels with a map. Java’s rules feel fussy at first — like bike lanes — but they stop whole classes of crashes and guide you downtown (jobs, Android, servers).',analogyFail:'Where it breaks: training wheels never win races. Java is verbose; tiny scripts are faster in Python. Java wins at big, long-lived apps.',explain:['<b>Java</b> (1995, now owned by Oracle, free OpenJDK builds) is general-purpose, <b>object-oriented</b>, and <b>statically typed</b> (you declare types; errors caught early).','Java builds: Android apps, server backends (banks, shops), desktop tools, Minecraft, and data systems.','Why learn it: strict compiler teaches discipline, huge job market, and skills transfer to C#, Kotlin, and more.'],code:`public class Hello {\n  public static void main(String[] args) {\n    System.out.println("Java runs everywhere!");\n  }\n}`,codeNotes:['Same shape as every Java app you will write.','println shows text on screen.','Curly braces group code together.'],output:'Java runs everywhere!',why:'The JVM runs this same bytecode on Windows, Mac, or Linux — write once, run anywhere.',sim:{kind:'concat',label:'Java strings join with +. Try it.',fields:[{v:'Java '},{v:'runs everywhere!'}]},mistakes:[{bad:'“Java and JavaScript are the same.”',why:'Different languages; similar names only.',fix:'Java = big apps; JavaScript = mostly web pages.'},{bad:'Expecting zero rules.',why:'Java asks for types and semicolons.',fix:'Treat errors as coaching, not failure.'},{bad:'Learning version 8 tricks only.',why:'Old tutorials linger.',fix:'We target Java 17 LTS — modern and supported.'}],practices:[{title:'Where is Java?',task:'Name 3 places Java runs (phone, bank, game…).',hint:'Think Android, servers, Minecraft.',sol:'Any 3: Android apps, bank servers, Minecraft, web backends, uni courses.'},{title:'Strict is helpful?',task:'Give one benefit of declaring types upfront.',hint:'When do you want to catch a mistake?',sol:'Compiler catches “apple + 5” before users suffer.'}],quiz:[{id:'q1',prompt:'Java is best described as…',options:[{t:'General-purpose, object-oriented, statically typed',ok:true},{t:'Only for web pages'},{t:'Same as JavaScript'},{t:'A computer brand'}],explain:'That trio is Java’s identity.'},{id:'q2',prompt:'“Write once, run anywhere” means…',options:[{t:'Same bytecode runs on many systems via JVM',ok:true},{t:'Write code one time ever'},{t:'No installation needed'},{t:'Runs without computers'}],explain:'The JVM abstracts the machine.'},{id:'q3',prompt:'Which is NOT typically Java?',options:[{t:'Tiny browser animation script',ok:true},{t:'Android app'},{t:'Bank backend'},{t:'Minecraft'}],explain:'Tiny web scripts favor JavaScript.'}],takeaways:['Java = strict, object-oriented, everywhere.','Powers Android, servers, games, tools.','We use modern Java 17 LTS.'],recall:'What does “statically typed” mean in one line?',todo:'Ask a friend: name one app; guess if Java could build it.',anim:{title:'Write once, run anywhere',steps:[{caption:'You write one Hello.java.',html:'<div class="pipe"><div class="box"><b>Hello.java</b><br>one source</div></div>'},{caption:'Compiler makes bytecode (.class).',html:'<div class="pipe"><div class="box"><b>javac</b></div><span class="arr">→</span><div class="box"><b>Hello.class</b><br>bytecode</div></div>'},{caption:'Each system’s JVM runs it.',html:'<div class="pipe"><div class="box">Windows JVM</div><div class="box">Mac JVM</div><div class="box">Linux JVM</div></div>'}]}},
'jdk-jre-jvm':{intro:'Three letters, one pipeline: JDK builds, JRE runs, JVM executes. Install the JDK and you get all three.',question:'Who writes the recipe, who owns the kitchen, and who actually cooks?',analogy:'Cookbook author (JDK tools) → equipped kitchen (JRE) → chef (JVM) cooking your dish. Author needs the kitchen; diners only need the kitchen + chef.',analogyFail:'Where it breaks: real kitchens vary. JVMs are deliberately identical — same bytecode behaves the same everywhere.',explain:['<b>JVM</b>: runs bytecode, manages memory. One per system, same behavior.','<b>JRE</b>: JVM + libraries to run apps (no compiler). For users.','<b>JDK</b>: JRE + javac compiler + tools. For developers. Install JDK 17 and you cover all.'],code:`# The pipeline you will use\njavac Hello.java   # JDK tool: source -> Hello.class\njava Hello         # JRE/JVM: run bytecode, print Hi`,codeNotes:['javac only exists in the JDK.','java runs using JRE + JVM.','Error at javac = syntax; at java = runtime.'],output:'Hi',why:'Compile once, then the JVM on any machine executes the bytecode.',sim:{kind:'concat',label:'No simulation — remember: JDK ⊃ JRE ⊃ JVM.',fields:[{v:'JDK '},{v:'includes JRE + JVM'}]},mistakes:[{bad:'Installing only JRE to code.',why:'JRE cannot compile.',fix:'Install JDK 17 (e.g., Temurin/Oracle).'},{bad:'“JVM is the compiler.”',why:'javac compiles; JVM runs.',fix:'javac = build, java = run.'},{bad:'Mixing Java 8 and 17 commands.',why:'Old javac + new java (or reverse) confuses.',fix:'Check java -version and javac -version match 17.'}],practices:[{title:'Who does what?',task:'Match: A) javac B) java C) JVM to: compiles / launches / executes.',hint:'Build → launch → execute.',sol:'A compiles, B launches, C executes bytecode.'},{title:'Which to install?',task:'You want to write Java. Friend only runs your app. What each installs?',hint:'Coders need the compiler.',sol:'You: JDK. Friend: JRE (or JDK, also fine).'}],quiz:[{id:'q1',prompt:'Which contains the compiler?',options:[{t:'JDK',ok:true},{t:'JRE only'},{t:'JVM only'},{t:'None'}],explain:'JDK = JRE + javac + tools.'},{id:'q2',prompt:'What runs bytecode?',options:[{t:'JVM',ok:true},{t:'Notepad'},{t:'javac'},{t:'The .java file'}],explain:'JVM executes + manages memory.'},{id:'q3',prompt:'javac Hello.java fails. What kind of problem?',options:[{t:'Compile/syntax — fix code, retry',ok:true},{t:'Computer is broken forever'},{t:'Internet is down'},{t:'Correct output'}],explain:'javac errors mean fix source first.'}],takeaways:['JVM runs, JRE runs-with-libraries, JDK builds.','Install JDK 17 for this course.','javac builds; java runs.'],recall:'What does each letter-group give you that the smaller one does not?',todo:'Run java -version in a terminal and note the number.',anim:{title:'JDK ⊃ JRE ⊃ JVM',steps:[{caption:'JVM: the chef executing.',html:'<div class="pipe"><div class="box"><b>JVM</b><br>executes bytecode</div></div>'},{caption:'JRE: kitchen + chef + ingredients.',html:'<div class="pipe"><div class="box"><b>JRE</b><br>JVM + libraries</div></div>'},{caption:'JDK: cookbook tools + whole kitchen.',html:'<div class="pipe"><div class="box"><b>JDK</b><br>JRE + javac + tools</div></div>'}]}},
'setup':{intro:'Time to cook for real: install JDK 17, write Hello.java, compile, run. Five minutes of setup pays off for the whole course.',question:'What is the smallest possible victory that proves your kitchen works?',analogy:'First pancake. It may look odd, but flipping one proves heat, pan, and batter. Hello World proves editor, compiler, and runner.',analogyFail:'Where it breaks: pancakes get eaten. Hello World gets kept — you will reuse this exact workflow for every lesson.',explain:['1 Install JDK 17 (Temurin or Oracle), 2 check <b>java -version</b>, 3 create <b>Hello.java</b>, 4 run <b>javac Hello.java</b>, 5 run <b>java Hello</b>.','File name must match class name: <b>Hello</b> in <b>Hello.java</b>. Case matters.','Read errors top-first: semicolon-expected means add a semicolon where it points.'],code:`public class Hello {\n  public static void main(String[] args) {\n    System.out.println("My kitchen works!");\n  }\n}\n// javac Hello.java\n// java Hello`,codeNotes:['Save exactly as Hello.java.','javac makes Hello.class.','java Hello prints the line.'],output:'My kitchen works!',why:'Compiler translated cleanly, JVM executed main, println showed output. Full loop works.',sim:{kind:'concat',label:'Simulate success: join your name to the greeting.',fields:[{v:'My kitchen works, '},{v:'Ada!'}]},mistakes:[{bad:'File named hello.java (lowercase).',why:'Java demands Hello == Hello.',fix:'Rename to Hello.java exactly.'},{bad:'Running javac Hello (no .java).',why:'javac wants the file; java wants the class.',fix:'javac Hello.java then java Hello.'},{bad:'“illegal start” or “; expected”.',why:'Typo in syntax.',fix:'Compare each line to the example; fix first error only.'}],practices:[{title:'Order the ritual',task:'Order: A) java Hello B) javac Hello.java C) save Hello.java.',hint:'Write → build → run.',sol:'C → B → A.'},{title:'Break it on purpose',task:'Remove one semicolon, run javac. What is the first error?',hint:'Read the line number it gives.',sol:'Error says a semicolon is expected, pointing at the line. Add it back.'}],quiz:[{id:'q1',prompt:'Correct workflow?',options:[{t:'Save → javac → java',ok:true},{t:'java → javac → save'},{t:'javac → save → java'},{t:'Only java, no save'}],explain:'Write, build, run.'},{id:'q2',prompt:'File/class rule?',options:[{t:'Public class Hello must live in Hello.java',ok:true},{t:'Any name works'},{t:'File must be .txt'},{t:'Class must be lowercase'}],explain:'Names match, case-sensitive.'},{id:'q3',prompt:'javac reports an error. You should…',options:[{t:'Fix the first error and rebuild',ok:true},{t:'Ignore and run java anyway'},{t:'Reinstall everything'},{t:'Delete the file'}],explain:'First error often causes the rest.'}],takeaways:['Install JDK 17; verify with java -version.','Save → javac → java, every time.','File name = class name, exactly.'],recall:'What two commands turn Hello.java into output?',todo:'Actually run Hello World on your machine now.',anim:{title:'Your first build',steps:[{caption:'1 Write Hello.java in editor.',html:'<div class="pipe"><div class="box"><b>Hello.java</b><br>println(...)</div></div>'},{caption:'2 javac translates to Hello.class.',html:'<div class="pipe"><div class="box"><b>javac</b></div><span class="arr">→</span><div class="box"><b>Hello.class</b></div></div>'},{caption:'3 java runs it. Output!',html:'<div class="pipe"><div class="box"><b>java Hello</b></div><span class="arr">→</span><div class="box"><b>My kitchen works!</b></div></div>'}]}},
'first-program':{intro:'Every Java program wears the same uniform: a class shell and a main door. Learn it once, recognize it forever.',question:'Why do all letters start with “Dear…” and end with a signature?',analogy:'Envelope + letter. Class = envelope with your name (Hello). main = “start reading here” arrow. JVM always opens the envelope at main.',analogyFail:'Where it breaks: you can read a letter anywhere. JVM must start at exactly main(String[] args) — no substitutes.',explain:['<b>public class Hello</b> names the blueprint. File must be Hello.java.','<b>public static void main(String[] args)</b> is the start door. Memorize its shape; meaning comes later.','Statements end with <b>;</b> Braces <b>{ }</b> group code. println prints + new line.'],code:`public class Hello {\n  public static void main(String[] args) {\n    System.out.println("Hello, Java!");\n    System.out.println("I am learning.");\n  }\n}`,codeNotes:['Line 1: envelope named Hello.','Line 2: start-here door.','Lines 3-4: two instructions, each ends with ;'],output:'Hello, Java!\nI am learning.',why:'JVM enters main, runs line 3 (print), then line 4, then exits. Order is top-down.',sim:{kind:'concat',label:'Predict output: join two lines.',fields:[{v:'Hello, '},{v:'Java!'}]},mistakes:[{bad:'main spelled Main or missing String[] args.',why:'JVM looks for the exact signature.',fix:'Copy exactly: public static void main(String[] args).'},{bad:'Forgetting the semicolon.',why:'Java cannot tell where instruction ends.',fix:'End every statement with ;'},{bad:'File Hello.java but class hello.',why:'Case mismatch breaks build.',fix:'Match exactly: Hello / Hello.java.'}],practices:[{title:'Label the uniform',task:'In the code, mark: envelope, door, instruction.',hint:'class / main / println.',sol:'Envelope: public class Hello. Door: main line. Instructions: println lines.'},{title:'Add a third line',task:'Print your name as a third line. Where does it go?',hint:'Inside main, before closing }.',sol:'Add System.out.println("Ada"); after line 4.'}],quiz:[{id:'q1',prompt:'Where does the JVM start?',options:[{t:'main(String[] args)',ok:true},{t:'Any line it likes'},{t:'The last line'},{t:'Comments'}],explain:'Fixed entry point.'},{id:'q2',prompt:'What ends a Java statement?',options:[{t:'Semicolon ;',ok:true},{t:'Period .'},{t:'New paragraph'},{t:'Emoji'}],explain:'; terminates statements.'},{id:'q3',prompt:'Class Hello must be in…',options:[{t:'Hello.java',ok:true},{t:'hello.java'},{t:'Hello.txt'},{t:'Anything'}],explain:'Exact match, case-sensitive.'}],takeaways:['Class = envelope; main = start door.','Statements end with ; braces group.','JVM runs main top-down.'],recall:'Write the main line from memory.',todo:'Type Hello by hand (do not copy) and run it.',anim:{title:'Entering main',steps:[{caption:'JVM finds the envelope Hello.',html:'<div class="pipe"><div class="box"><b>Hello.class</b><br>envelope</div></div>'},{caption:'Opens the door: main.',html:'<div class="pipe"><div class="box"><b>main</b><br>start here →</div></div>'},{caption:'Runs each println top-down.',html:'<div class="pipe"><div class="box">Hello, Java!</div><span class="arr">→</span><div class="box">I am learning.</div></div>'}]}},
'printing':{intro:'Printing is your X-ray: show values, test guesses, and make friendly output. Master println vs print in ten minutes.',question:'How do you check what is inside a wrapped box without opening your program’s brain?',analogy:'Label printer. println prints a label and feeds a new line; print stays on the same line; printf fills a form with blanks (“name: ___, age: ___”).',analogyFail:'Where it breaks: printers use ink. println uses text only — no colors or fonts without extra tools.',explain:['<b>println</b> prints + newline. <b>print</b> stays on the line. Combine for layouts.','Text goes in <b>"quotes"</b>; numbers bare. <b>+</b> joins pieces.','<b>printf</b> formats: %d integer, %.2f two decimals, %s text, %n newline.'],code:`System.out.println("Apples: " + 3);\nSystem.out.print("Total: ");\nSystem.out.println(3 * 2);\nSystem.out.printf("Price: $%.2f%n", 2.5);`,codeNotes:['Line 1 joins text + number → Apples: 3.','Lines 2-3 share one line: Total: 6.','Line 4 formats 2.5 as $2.50.'],output:'Apples: 3\nTotal: 6\nPrice: $2.50',why:'+ with a string makes a string. 3*2 = 6 stays on the print line. printf rounds to 2 decimals.',sim:{kind:'concat',label:'Build a label: text + number.',fields:[{v:'Apples: '},{v:'3'}]},mistakes:[{bad:'println("3 + 2") expecting 5.',why:'Quotes mean literal text.',fix:'Remove quotes: println(3 + 2); // 5'},{bad:'Forgetting + between pieces.',why:'Java cannot glue by adjacency.',fix:'"Apples: " + 3.'},{bad:'printf without %n.',why:'Next output sticks to same line.',fix:'End format with %n.'}],practices:[{title:'Predict it',task:'What prints? System.out.print("A"); System.out.println("B"); System.out.println("C");',hint:'print stays, println breaks.',sol:'AB on line 1, C on line 2.'},{title:'Format money',task:'Print 19.9 as $19.90 with printf.',hint:'%.2f and %n.',sol:'System.out.printf("$%.2f%n", 19.9);'}],quiz:[{id:'q1',prompt:'println vs print?',options:[{t:'println adds a new line; print does not',ok:true},{t:'print is faster to type only'},{t:'They are identical'},{t:'print deletes text'}],explain:'The ln = line break.'},{id:'q2',prompt:'System.out.println(3 + 2) prints?',options:[{t:'5',ok:true},{t:'3 + 2'},{t:'32'},{t:'Error'}],explain:'No quotes → math happens.'},{id:'q3',prompt:'%.2f formats…',options:[{t:'A decimal with 2 places',ok:true},{t:'An integer'},{t:'Text centered'},{t:'A date'}],explain:'f = float, .2 = two places.'}],takeaways:['println breaks line; print does not.','+ joins text; bare numbers compute.','printf formats with %d %.2f %s.'],recall:'When would you pick print over println?',todo:'Print a tiny receipt: 3 lines + formatted total.',anim:{title:'Print heads',steps:[{caption:'print stays on the line.',html:'<div class="pipe"><div class="box"><b>print("Total: ")</b><br>cursor waits…</div></div>'},{caption:'println feeds a new line.',html:'<div class="pipe"><div class="box"><b>println(6)</b><br>Total: 6 ⏎</div></div>'},{caption:'printf fills blanks precisely.',html:'<div class="pipe"><div class="box"><b>$%.2f</b><br>2.5 → 2.50</div></div>'}]}},
'comments':{intro:'Code tells what; comments tell why. Future you will thank present you — write both for humans.',question:'Why do museums put little plaques next to paintings?',analogy:'Museum plaque. The painting (code) shows; the plaque (comment) explains why it matters and what to notice. No plaque on every brushstroke.',analogyFail:'Where it breaks: plaques never repaint. Comments never run — wrong comments actively mislead. Update or delete them.',explain:['<b>//</b> comments one line. <b>/* */</b> spans many. <b>/** */</b> documents for tools.','Comment the <b>why</b>, not the what: // discounts apply after 18:00 (law), not // add 1.','Clear names beat comments: <b>adultAge</b> needs none; <b>x2</b> needs rescue.'],code:`// Good: explains WHY\nint adultAge = 18; // law in our town\n/* Long note:\n   Prices include tax.\n   Change taxRate in one place. */\nSystem.out.println(adultAge);`,codeNotes:['Comment the rule source (law).','Block comment warns about tax design.','Code itself stays clean.'],output:'18',why:'Comments vanish at compile; only println runs. Readers still learn the rule.',sim:{kind:'concat',label:'Comments change nothing — output stays.',fields:[{v:'18'},{v:' (comment ignored)'}]},mistakes:[{bad:'// adds one to x then x++;',why:'Restates the obvious; noise.',fix:'Explain why: // retry count resets after logout.'},{bad:'Old comment lies: // max 5 when code allows 10.',why:'Stale comments mislead.',fix:'Update with code or delete.'},{bad:'Commenting out code as “backup”.',why:'Rot piles up.',fix:'Delete; git remembers.'}],practices:[{title:'Keep or kill?',task:'Which comment helps? A) // increment i, i++ B) // retry 3x: server drops first ping.',hint:'Why > what.',sol:'B helps; A restates.'},{title:'Name it well',task:'Rename int d (days until trip) + comment if needed.',hint:'Good name may need no comment.',sol:'int daysUntilTrip; // no comment needed.'}],quiz:[{id:'q1',prompt:'Which comment style is one line?',options:[{t:'//',ok:true},{t:'/* */'},{t:'<!-- -->'},{t:'#'}],explain:'// to end of line.'},{id:'q2',prompt:'Best comment?',options:[{t:'Why this rule/value exists',ok:true},{t:'Restating the code'},{t:'Your lunch plans'},{t:'Deleted code backup'}],explain:'Why survives; what is visible.'},{id:'q3',prompt:'Do comments affect running?',options:[{t:'No — removed before run',ok:true},{t:'Yes, they speed it up'},{t:'Yes, they print'},{t:'Only on Fridays'}],explain:'For humans only.'}],takeaways:['// line, /* */ block, /** */ docs.','Comment why, name what.','Stale comments are bugs in prose.'],recall:'What should a comment explain that code cannot?',todo:'Add one why-comment to your Hello program.',anim:{title:'Plaque vs painting',steps:[{caption:'Code paints (runs).',html:'<div class="pipe"><div class="box"><b>println(18)</b><br>paints 18</div></div>'},{caption:'Comment plaques (ignored by JVM).',html:'<div class="pipe"><div class="box"><b>// law: 18</b><br>for humans</div></div>'},{caption:'Together: clear + correct.',html:'<div class="pipe"><div class="box"><b>adultAge = 18</b><br>+ why note</div></div>'}]}},
'variables':{intro:'A variable is a labelled lunchbox: one box, one kind of food, one name tag. Put things in, look, replace.',question:'If your desk had 100 unlabeled drawers, how fast could you find your charger?',analogy:'Labelled lunchboxes on a shelf. Type = “soup only” sticker, name = “Aarav’s”, value = today’s soup. Swap soup anytime; sticker stays.',analogyFail:'Where it breaks: real boxes hold anything. Java boxes hold one declared type — soup box refuses sandwiches (compiler error).',explain:['Declare: <b>int age = 18;</b> — type, name, starting value. Use <b>=</b> to store (assignment, not equality).','Names: start letter, camelCase (userAge), meaningful. Case-sensitive.','Reassign anytime: <b>age = 19;</b> replaces the old value; the box is reused.'],code:`int age = 17;          // declare + initialize\nSystem.out.println(age); // 17\nage = 18;               // update (birthday!)\nSystem.out.println(age); // 18`,codeNotes:['Line 1 creates box age with 17.','Line 3 replaces content with 18.','Old 17 is gone — one value at a time.'],output:'17\n18',why:'First print reads 17; assignment overwrites; second print reads 18.',sim:{kind:'arith',label:'Simulate a box: compute a new value to store.',fields:[{v:'17'},{o:['+']},{v:'1'}]},mistakes:[{bad:'int age; System.out.println(age);',why:'Empty box — Java refuses to guess (local vars).',fix:'Initialize: int age = 0;'},{bad:'age = "old"; (age is int)',why:'Wrong food in box.',fix:'Keep type: age = 19; or use String label.'},{bad:'Using = when meaning ==.',why:'= stores; == compares (later lesson).',fix:'Store with =, compare with ==.'}],practices:[{title:'Trace it',task:'int x = 2; x = x + 3; print x. What shows?',hint:'Right side computes first, then stores.',sol:'5. x+3 = 5 stored back into x.'},{title:'Name them',task:'Name boxes for: user city, score. Declare with starting values.',hint:'camelCase, types String/int.',sol:'String userCity = "Pune"; int score = 0;'}],quiz:[{id:'q1',prompt:'int age = 18 means…',options:[{t:'Create int box “age” holding 18',ok:true},{t:'Check if age equals 18'},{t:'Create 18 boxes'},{t:'Delete age'}],explain:'Declare + initialize in one line.'},{id:'q2',prompt:'After age = 19, the old 17…',options:[{t:'Is replaced',ok:true},{t:'Stays alongside'},{t:'Doubles'},{t:'Moves to another box'}],explain:'One box, one current value.'},{id:'q3',prompt:'Why initialize before use?',options:[{t:'Java will not guess empty boxes',ok:true},{t:'It runs faster'},{t:'Boxes look nicer'},{t:'Required by printers'}],explain:'Definite assignment rule.'}],takeaways:['Variable = type + name + value.','= stores; names are camelCase.','One box holds one current value.'],recall:'What three parts does every variable have?',todo:'Store your age and city, print both.',anim:{title:'Lunchbox assignment',steps:[{caption:'Declare: new labelled box with soup 17.',html:'<div class="viz"><div class="varbox"><div class="nm">int age</div><div class="vl">17</div></div></div>'},{caption:'Read: peek without emptying.',html:'<div class="viz"><div class="varbox"><div class="nm">age</div><div class="vl">17 → print</div></div></div>'},{caption:'Update: swap to 18. Old gone.',html:'<div class="viz"><div class="varbox"><div class="nm">age</div><div class="vl">18 ✨</div></div></div>'}]}},
'primitives':{intro:'Java has exactly 8 built-in value types. Pick the smallest box that safely fits — usually int, double, boolean, char.',question:'Why sell milk in 250ml, 500ml, and 1L — not just one giant tanker?',analogy:'Measuring cups. byte (tiny espresso), int (mug), long (bucket), float/double (graduated cylinders), char (single letter tile), boolean (light switch).',analogyFail:'Where it breaks: cups spill visibly. Numeric overflow wraps silently (127 + 1 → -128 in byte). Choose big enough!',explain:['Integers: <b>byte</b> ±128, <b>short</b> ±32k, <b>int</b> ±2 billion (default), <b>long</b> huge (add L).','Decimals: <b>float</b> ~7 digits (add f), <b>double</b> ~15 digits (default for 3.5). Use double unless told otherwise.','<b>char</b> one UTF-16 unit (like a), <b>boolean</b> true/false. char is a number underneath (A = 65).'],code:`int people = 30;\nlong worldPop = 8_000_000_000L;\ndouble price = 19.99;\nfloat temp = 36.6f;\nchar grade = 'A';\nboolean passed = true;\nSystem.out.println(people + " " + price + " " + grade);`,codeNotes:['L marks long; f marks float.','3.5 alone is double.','char uses single quotes.'],output:'30 19.99 A',why:'Each literal fits its type; + with strings joins for display.',sim:{kind:'arith',label:'Integers vs decimals: try 5 / 2 as int math.',fields:[{v:'5'},{o:['/']},{v:'2'}]},mistakes:[{bad:'long x = 8000000000; (no L)',why:'Bare number is int — too big!',fix:'long x = 8_000_000_000L;'},{bad:'float t = 36.6; (no f)',why:'36.6 is double; cannot squeeze silently.',fix:'float t = 36.6f; or use double.'},{bad:'char c = "a";',why:'Double quotes = String, not char.',fix:"char c = 'a';"}],practices:[{title:'Pick types',task:'Choose types: person age, planet population, pi, grade letter, light on/off.',hint:'int, long, double, char, boolean.',sol:'int age; long population; double pi; char grade; boolean on.'},{title:'char math?',task:'What is (int) \'A\'? Guess, then run.',hint:'Unicode number underneath.',sol:'65. (int) shows the code unit.'}],quiz:[{id:'q1',prompt:'Default type of 3.5?',options:[{t:'double',ok:true},{t:'float'},{t:'int'},{t:'char'}],explain:'Decimals default to double.'},{id:'q2',prompt:'Which needs a suffix?',options:[{t:'long big = 8000000000L',ok:true},{t:'int n = 5'},{t:'boolean b = true'},{t:'char c = globals'}],explain:'Big longs need L; floats need f.'},{id:'q3',prompt:'byte b = 127; b + 1 becomes?',options:[{t:'-128 (overflow wraps)',ok:true},{t:'128 safely'},{t:'Error always'},{t:'0 exactly'}],explain:'Tiny types wrap — pick bigger.'}],takeaways:['8 primitives; default int and double.','L for long, f for float, single quotes for char.','Overflow wraps: size your box.'],recall:'Name the 8 primitives without peeking.',todo:'Declare one variable of each of int, double, char, boolean and print them.',anim:{title:'Sizing boxes',steps:[{caption:'byte: espresso cup (-128..127).',html:'<div class="viz"><div class="varbox"><div class="nm">byte</div><div class="vl">127</div></div></div>'},{caption:'int: everyday mug (±2B).',html:'<div class="viz"><div class="varbox"><div class="nm">int</div><div class="vl">2,147,483,647</div></div></div>'},{caption:'Overflow: one more sip spills to -128.',html:'<div class="viz"><div class="varbox"><div class="nm">byte+1</div><div class="vl">-128 ⚠️</div></div></div>'}]}},
'references':{intro:'Primitives hold values. References hold directions to objects — like a home address, not the house itself.',question:'If you copy a house key, do you copy the house?',analogy:'House addresses. Two slips can point to one house (shared). Primitives are cash in hand; references are address slips to houses (objects).',analogyFail:'Where it breaks: addresses never build houses. You must new the house first — a slip saying null points nowhere and crashes if visited.',explain:['<b>Primitive</b> int x = 5 holds 5. <b>Reference</b> String s holds directions to a text object.','<b>new</b> builds the house: StringBuilder sb = new StringBuilder(). Without new, reference may be <b>null</b>.','Copying a reference shares the house: Book b2 = b1 means one book, two slips. Change via one, see via both.'],code:`String a = "hello";\nString b = a;              // same house, two slips\nStringBuilder sb = new StringBuilder("hi");\nsb.append("!");\nSystem.out.println(a + " / " + b + " / " + sb);`,codeNotes:['b = a shares the same string.','new builds a fresh builder house.','append changes the shared house.'],output:'hello / hello / hi!',why:'a and b point to one string. sb points to a builder we mutated to hi!.',sim:{kind:'concat',label:'Sharing: two names, one text.',fields:[{v:'hello'},{v:' (shared)'}]},mistakes:[{bad:'“Reference contains the whole object.”',why:'It holds directions; object lives on the heap.',fix:'Say: s points to a String.'},{bad:'Using null blindly: s.length() when s is null.',why:'No house at null — NullPointerException.',fix:'Check: if (s != null) ...'},{bad:'Expecting b = a to copy the house.',why:'Only the slip copies; house shared.',fix:'To clone, build new: new StringBuilder(a).'}],practices:[{title:'Shared or not?',task:'int x=5; int y=x; x=9. What is y? Then String a="h"; String b=a. Same idea?',hint:'Primitives copy value; references copy direction.',sol:'y stays 5 (copy of value). b shares the string house.'},{title:'Null guard',task:'Write a safe length: return 0 if s is null.',hint:'if (s == null).',sol:'if (s == null) return 0; return s.length();'}],quiz:[{id:'q1',prompt:'A reference variable holds…',options:[{t:'Directions to an object (or null)',ok:true},{t:'The entire object inside'},{t:'Only numbers'},{t:'Nothing ever'}],explain:'Address slip, not the house.'},{id:'q2',prompt:'Book b2 = b1 means…',options:[{t:'One book, two references',ok:true},{t:'Two separate books'},{t:'No books'},{t:'A compiler error'}],explain:'Slip copied; house shared.'},{id:'q3',prompt:'Calling a method on null gives…',options:[{t:'NullPointerException',ok:true},{t:'A bigger house'},{t:'Zero always'},{t:'Nothing, safely'}],explain:'Nowhere to visit — crash.'}],takeaways:['Primitives hold values; references point.','new builds; null points nowhere.','Copying a reference shares the object.'],recall:'Cash vs address slip: which is primitive?',todo:'Draw boxes-and-arrows for String a and b = a.',anim:{title:'Slips and houses',steps:[{caption:'Primitive: cash in hand.',html:'<div class="viz"><div class="varbox"><div class="nm">int x</div><div class="vl">5</div></div></div>'},{caption:'Reference: slip → house.',html:'<div class="pipe"><div class="box"><b>s</b><br>slip ➜</div><span class="arr">→</span><div class="box"><b>"hello" 🏠</b><br>object</div></div>'},{caption:'b = a: two slips, one house.',html:'<div class="pipe"><div class="box"><b>a ➜ 🏠</b></div><div class="box"><b>b ➜ 🏠</b></div></div>'}]}},
'literals':{intro:'Literals are values typed directly: 42, 3.5, single letters, quoted text, true. Constants (final) give them names so magic numbers vanish.',question:'Why do buildings label “EXIT” instead of painting mysterious green rectangles?',analogy:'Name tags vs sticky notes. 3.14159 scribbled everywhere = sticky notes. final double PI = 3.14159 = engraved tag — one truth, reused safely.',analogyFail:'Where it breaks: engraved tags cannot change. final is a promise — reassigning breaks the build on purpose.',explain:['Integer literals are <b>int</b> (add <b>L</b> for long). Decimals are <b>double</b> (add <b>f</b> for float).','<b>Single-quoted</b> char vs <b>double-quoted</b> String. <b>true/false</b>, and underscores: 1_000_000.','<b>final double PI = 3.14159;</b> names a constant. UPPER_CASE by convention; set once.'],code:`final double PI = 3.14159;\nint count = 1_000;\nlong big = 5_000_000_000L;\nfloat ratio = 0.5f;\nchar first = 'J';\ndouble circle = PI * 2 * 2; // r=2\nSystem.out.println(circle);`,codeNotes:['PI named once, reused.','_ only helps humans read.','L and f pick the right type.'],output:'12.56636',why:'PI × 2 × r with r=2 gives 2πr ≈ 12.566. Named constant keeps it correct everywhere.',sim:{kind:'arith',label:'Constants keep math honest. Try radius math.',fields:[{v:'3.14159'},{o:['*']},{v:'4'}]},mistakes:[{bad:'double x = 3.14159; scattered 20 times.',why:'Change means 20 edits + misses.',fix:'final double PI = 3.14159; reuse PI.'},{bad:'PI = 3.0; after final.',why:'Final forbids reassign.',fix:'Remove final or keep one assignment.'},{bad:'char c = "J";',why:'String ≠ char.',fix:"char c = 'J';"}],practices:[{title:'Name the magic',task:'Replace 0.18 tax in price * 0.18 with a constant.',hint:'final double TAX_RATE = 0.18;',sol:'final double TAX_RATE = 0.18; price * TAX_RATE;'} ,{title:'Spot literal types',task:'Types of: 7, 7L, 7.0, 7.0f, \'7\', "7"?',hint:'int, long, double, float, char, String.',sol:'int, long, double, float, char, String.'}],quiz:[{id:'q1',prompt:'3.5 is which type by default?',options:[{t:'double',ok:true},{t:'float'},{t:'int'},{t:'long'}],explain:'Decimals default double.'},{id:'q2',prompt:'final means…',options:[{t:'Set once, then locked',ok:true},{t:'Secret value'},{t:'Faster typing'},{t:'Bigger number'}],explain:'Single assignment promise.'},{id:'q3',prompt:"'a' vs \"a\"?",options:[{t:'char vs String',ok:true},{t:'Same thing'},{t:'String vs char'},{t:'Both numbers'}],explain:'Single = char, double = String.'}],takeaways:['Literals have default types; suffixes override.','Name magic numbers as UPPER_CASE final.','Single quotes char, double quotes String.'],recall:'What literal needs L and what needs f?',todo:'Replace one magic number in old code with a final constant.',anim:{title:'Sticky notes → name tags',steps:[{caption:'Magic numbers everywhere.',html:'<div class="pipe"><div class="box">0.18 … 0.18 … 0.18</div></div>'},{caption:'One engraved tag.',html:'<div class="viz"><div class="varbox"><div class="nm">TAX_RATE</div><div class="vl">0.18 🔒</div></div></div>'},{caption:'Reuse safely; change once.',html:'<div class="pipe"><div class="box">price × TAX_RATE</div><span class="arr">→</span><div class="box">always right</div></div>'}]}},
'casting':{intro:'Sometimes a big value must fit a small box (narrowing) or a small one joins big math (widening). Java is picky — explicitly cast when you might lose something.',question:'What happens pouring a bucket into a mug?',analogy:'Funnel vs bucket. Widening (mug → bucket, int → long) always fits, automatic. Narrowing (bucket → mug, double → int) spills — you must sign “I accept spills” with (int).',analogyFail:'Where it breaks: funnels do not round — they chop. (int) 3.99 = 3, not 4. Casting truncates toward zero.',explain:['<b>Widening</b> automatic: int → long → double. No loss, no cast.','<b>Narrowing</b> needs cast: (int) 3.9 → 3, (byte) 130 → -126. Data may change!','<b>byte/short/char</b> math becomes int. Division: 5/2 = 2 (int), 5/2.0 = 2.5.'],code:`int a = 5, b = 2;\nSystem.out.println(a / b);     // 2 (int!)\nSystem.out.println(a / 2.0);   // 2.5\ndouble d = 3.99;\nint n = (int) d;              // 3, chopped\nSystem.out.println(n);`,codeNotes:['int/int stays int — truncation.','One double lifts math to double.','Cast chops, never rounds.'],output:'2\n2.5\n3',why:'Integer division truncates. 2.0 widens the expression. (int) chops .99.',sim:{kind:'arith',label:'Feel truncation: divide ints.',fields:[{v:'5'},{o:['/']},{v:'2'}]},mistakes:[{bad:'double avg = sum / count; (both int)',why:'Right side truncates before storing!',fix:'double avg = (double) sum / count;'},{bad:'int n = 3.9;',why:'Narrowing needs explicit permission.',fix:'int n = (int) 3.9; // 3'},{bad:'Expecting (int) to round.',why:'It chops toward zero.',fix:'Round: (int) Math.round(3.9); // 4'}],practices:[{title:'Fix the average',task:'int s=7, c=2. Make avg 3.5 not 3.',hint:'Cast before dividing.',sol:'double avg = (double) s / c;'} ,{title:'Predict chop',task:'(int) -3.9 and (int) 130 as byte? (guess)',hint:'Toward zero; bytes wrap.',sol:'-3 and -126.'}],quiz:[{id:'q1',prompt:'5 / 2 in Java (both int)?',options:[{t:'2',ok:true},{t:'2.5'},{t:'3'},{t:'Error'}],explain:'Int division truncates.'},{id:'q2',prompt:'(int) 3.99 gives?',options:[{t:'3',ok:true},{t:'4'},{t:'3.99'},{t:'0'}],explain:'Chop toward zero.'},{id:'q3',prompt:'Which is automatic (safe)?',options:[{t:'int → double',ok:true},{t:'double → int'},{t:'long → byte'},{t:'double → float'}],explain:'Widening fits; narrowing needs cast.'}],takeaways:['Widening auto; narrowing needs (type).','int/int truncates — cast first for decimals.','Casts chop; Math.round rounds.'],recall:'How do you get 2.5 from ints 5 and 2?',todo:'Find one division in your code; check int vs double.',anim:{title:'Bucket vs mug',steps:[{caption:'Widening: mug → bucket, auto.',html:'<div class="pipe"><div class="box"><b>int 5</b></div><span class="arr">→</span><div class="box"><b>double 5.0</b> ✓</div></div>'},{caption:'Narrowing: bucket → mug spills.',html:'<div class="pipe"><div class="box"><b>3.99</b></div><span class="arr">→</span><div class="box"><b>(int) 3</b> ⚠️ chop</div></div>'},{caption:'int/int: 5/2 = 2, remainder lost.',html:'<div class="viz"><div class="varbox"><div class="nm">5 / 2</div><div class="vl">2</div></div></div>'}]}},
'operators':{intro:'Operators are verbs: math (+ - * / %), compare (== != < >), and combine (&& || !). Precedence decides who goes first.',question:'Why does “2 + 3 × 4” confuse even adults?',analogy:'Canteen line with VIPs. × ÷ % go first (VIP), + − next, comparisons after, && then || last. Brackets are the teacher letting anyone jump the queue.',analogyFail:'Where it breaks: VIP order is convention, not physics. When unsure, add brackets — explicit beats clever.',explain:['<b>Arithmetic</b>: + - * / % (remainder). <b>+= -= *= /= %=</b> update in place. <b>++ --</b> step by one.','<b>Compare</b>: == != < <= > >= give boolean. <b>Logic</b>: && (both), || (either), ! (flip).','<b>&& and || short-circuit</b>: stop early when decided — also guards null/zero safely.'],code:`int age = 20;\nboolean teen = age >= 13 && age <= 19;\nSystem.out.println(teen); // false\nint r = 7 % 3;            // 1\nint x = 5; x += 2;         // 7\nSystem.out.println(r + " " + x);`,codeNotes:['&& needs both true; 20 fails teen.','7 % 3 = 1 (leftover).','x += 2 means x = x + 2.'],output:'false\n1 7',why:'20 is not ≤19, so teen false. Remainder 1. x grows to 7.',sim:{kind:'arith',label:'Try % (remainder) — great for even/odd.',fields:[{v:'7'},{o:['%']},{v:'3'}]},mistakes:[{bad:'if (x = 5) — single =.',why:'= stores 5, not a question.',fix:'if (x == 5).'},{bad:'2 + 3 * 4 expected 20.',why:'* first: 2+12=14.',fix:'(2 + 3) * 4 for 20.'},{bad:'Comparing strings with ==.',why:'== checks same house, not same text.',fix:'Use word.equals(other) — next lessons.'}],practices:[{title:'Even or odd?',task:'Write boolean isEven for n using %.',hint:'n % 2 == 0.',sol:'boolean isEven = (n % 2 == 0);'},{title:'Add brackets',task:'Rewrite 2 + 3 * 4 - 6 / 2 with brackets showing order.',hint:'* / first.',sol:'2 + (3*4) - (6/2) = 11.'}],quiz:[{id:'q1',prompt:'7 % 3 = ?',options:[{t:'1',ok:true},{t:'2'},{t:'2.33'},{t:'0'}],explain:'Remainder after 3+3.'},{id:'q2',prompt:'x += 2 means…',options:[{t:'x = x + 2',ok:true},{t:'x == 2'},{t:'x = 2'},{t:'x + 2 ignored'}],explain:'Shorthand update.'},{id:'q3',prompt:'a && b is true when…',options:[{t:'Both a and b are true',ok:true},{t:'Either is true'},{t:'Both false'},{t:'Always true'}],explain:'AND needs both.'}],takeaways:['% gives remainder — perfect for cycles.','= stores, == compares.','Brackets beat memorizing precedence.'],recall:'What does short-circuit mean for &&?',todo:'Write teen-check for your own age and print it.',anim:{title:'VIP queue',steps:[{caption:'× ÷ % jump first.',html:'<div class="pipe"><div class="box">3 × 4 = 12 (VIP)</div></div>'},{caption:'+ − go next.',html:'<div class="pipe"><div class="box">2 + 12 = 14</div></div>'},{caption:'Brackets overrule everything.',html:'<div class="pipe"><div class="box">(2+3) × 4 = 20 🎓</div></div>'}]}},
'strings':{intro:'Text rules every app — names, messages, files. In Java, text is a String object with superpowers, joined by +.',question:'How do you sew two ribbons into one longer ribbon?',analogy:'Bead strings. Each String is beads on a thread; + knots two threads together into a new longer one (originals unchanged — immutability preview!).',analogyFail:'Where it breaks: real knots hold originals. + makes a brand-new string; old pieces remain. Also == compares knots, not beads — use equals.',explain:['Create: <b>String name = "Ada";</b> Join: <b>"Hi " + name</b>. Numbers join too: "Age: " + 18.','Key tools (preview): <b>length()</b>, <b>equals()</b>, <b>+</b>. Full tour in Stage 4.','Empty vs blank: <b>""</b> length 0; <b>" "</b> has a space. Watch out!'],code:`String name = "Ada";\nint age = 18;\nString msg = "Hi " + name + ", age " + age;\nSystem.out.println(msg);\nSystem.out.println("len=" + msg.length());`,codeNotes:['+ with a string makes everything text.','msg is a new string; parts unchanged.','length() counts every character.'],output:'Hi Ada, age 18\nlen=14',why:'Pieces knot into one new string. Length counts letters, spaces, comma, digits.',sim:{kind:'concat',label:'Sew ribbons: join two texts.',fields:[{v:'Hi '},{v:'Ada'}]},mistakes:[{bad:'if (name == "Ada")',why:'== compares houses, not beads.',fix:'if (name.equals("Ada")).'},{bad:'"Age: " + 18 + 2 expecting 20.',why:'Left-to-right: "Age: 18" + 2 = "Age: 182".',fix:'"Age: " + (18 + 2).'},{bad:'Forgetting space: "Hi"+name.',why:'Knots have no auto-space.',fix:'"Hi " + name.'}],practices:[{title:'Fix equality',task:'Fix: if (city == "Pune") ...',hint:'equals for text.',sol:'if (city.equals("Pune")) ...'},{title:'Build a badge',task:'Make "Ada (18)" from name + age with brackets + space.',hint:'"(" + age + ")"',sol:'String badge = name + " (" + age + ")";'}],quiz:[{id:'q1',prompt:'"Hi " + "Ada" gives?',options:[{t:'Hi Ada',ok:true},{t:'HiAda+?'},{t:'Error'},{t:'Hi, Ada, Hi'}],explain:'+ knots strings.'},{id:'q2',prompt:'Compare string contents with…',options:[{t:'.equals()',ok:true},{t:'=='},{t:'='},{t:'!='},],explain:'equals checks beads; == checks knots.'},{id:'q3',prompt:'"Age: " + 18 + 2 = ?',options:[{t:'Age: 182',ok:true},{t:'Age: 20'},{t:'38'},{t:'Error'}],explain:'Left-to-right string math.'}],takeaways:['String = text object; + knots new ones.','Compare text with equals, not ==.','length() counts all characters.'],recall:'Why does "a" + 1 + 2 differ from "a" + (1+2)?',todo:'Print a greeting badge with your name and city.',anim:{title:'Knot ribbons',steps:[{caption:'Two ribbons: "Hi " and "Ada".',html:'<div class="pipe"><div class="box">"Hi "</div><div class="box">"Ada"</div></div>'},{caption:'+ knots a NEW ribbon.',html:'<div class="pipe"><div class="box">"Hi "</div><span class="arr">+</span><div class="box">"Ada"</div><span class="arr">→</span><div class="box"><b>"Hi Ada"</b> ✨</div></div>'},{caption:'Originals unchanged.',html:'<div class="pipe"><div class="box">"Hi " still</div><div class="box">"Ada" still</div></div>'}]}},
'scanner':{intro:'Programs come alive when they listen. Scanner reads keyboard words and numbers — with one famous trap you will now dodge.',question:'Why do ATMs ask one question at a time and wait?',analogy:'Curious cashier. nextInt grabs a number token, nextLine grabs the whole sentence tray. After a number, a leftover newline sits on the tray — cashier trips unless you clear it.',analogyFail:'Where it breaks: cashiers forgive. Scanner does not — wrong token (abc for a number) crashes with InputMismatchException. Validate!',explain:['<b>new Scanner(System.in)</b>, then <b>nextInt()</b>, <b>nextDouble()</b>, <b>next()</b> (one word), <b>nextLine()</b> (whole line).','Trap: after nextInt(), call an extra <b>nextLine()</b> to eat the leftover newline.','Close with <b>in.close()</b> (or leave System.in open in tiny apps). Check <b>hasNextInt()</b> to validate.'],code:`import java.util.Scanner;\npublic class Ask {\n  public static void main(String[] args) {\n    Scanner in = new Scanner(System.in);\n    System.out.print("Age: ");\n    int age = in.nextInt();\n    in.nextLine(); // eat leftover newline\n    System.out.print("Name: ");\n    String name = in.nextLine();\n    System.out.println("Hi " + name + ", " + age);\n  }\n}`,codeNotes:['nextInt reads number, leaves \\n.','Extra nextLine clears it.','nextLine then reads the real name.'],output:'Age: 18\nName: Ada\nHi Ada, 18',why:'Clearing the leftover newline lets the name read correctly instead of an empty string.',sim:{kind:'concat',label:'Simulate greeting assembly.',fields:[{v:'Ada'},{v:', 18'}]},mistakes:[{bad:'Skipped name (empty string).',why:'Leftover newline eaten as “answer”.',fix:'Add in.nextLine() after nextInt().'},{bad:'Typing abc for nextInt().',why:'Token mismatch crashes.',fix:'Check in.hasNextInt() or catch exception.'},{bad:'next() for full name.',why:'next() stops at space: “Ada Lovelace” → “Ada”.',fix:'Use nextLine() for sentences.'}],practices:[{title:'Fix the skip',task:'Age then city skips. Add the one-line fix.',hint:'Eat newline after number.',sol:'Insert in.nextLine(); after nextInt().'},{title:'Mini Q&A',task:'Ask favorite food (line) + rating (int). Print “Food: X, 5/5”.',hint:'Number first? Remember the trap.',sol:'Read int, eat newline, read line, print joined.'}],quiz:[{id:'q1',prompt:'After nextInt(), nextLine() skips. Fix?',options:[{t:'Extra nextLine() to eat newline',ok:true},{t:'Restart computer'},{t:'Use only nextInt'},{t:'Delete Scanner'}],explain:'Consume the leftover \\n.'},{id:'q2',prompt:'Read full name “Ada L”?',options:[{t:'nextLine()',ok:true},{t:'nextInt()'},{t:'next()'},{t:'nextDouble()'}],explain:'Whole line including spaces.'},{id:'q3',prompt:'User types abc for nextInt. What?',options:[{t:'InputMismatchException',ok:true},{t:'Prints abc nicely'},{t:'Reads 0 silently'},{t:'Nothing'}],explain:'Wrong token type crashes.'}],takeaways:['Scanner listens: nextInt/next/nextLine.','Eat newline after numbers.','nextLine for sentences; validate input.'],recall:'What does the “extra nextLine” eat?',todo:'Build a 2-question Q&A and run it on a friend.',anim:{title:'The newline trap',steps:[{caption:'Type 18 ⏎: number taken, ⏎ left.',html:'<div class="pipe"><div class="box"><b>Tray</b><br>18 | ⏎ leftover</div></div>'},{caption:'nextLine eats ⏎ → name reads "".[empty]',html:'<div class="pipe"><div class="box">name = "" 😱</div></div>'},{caption:'Fix: extra nextLine clears tray first.',html:'<div class="pipe"><div class="box">eat ⏎</div><span class="arr">→</span><div class="box">name = "Ada" ✓</div></div>'}]}},
};
